const shortNames=['Kukatpally','Nizampet','Mehdipatnam','Miyapur A/C','Gokul non-A/C','Gokul A/C','Gokul semi-A/C','Miyapur girls','Gudimalkapur'];
const total=(xs:number[])=>xs.reduce((a,b)=>a+b,0);
const mean=(xs:number[])=>xs.length?total(xs)/xs.length:0;
const percent=(x:number,y:number)=>y?100*x/y:0;
const fmt=(v:number)=>v.toFixed(1)+'%';
const score=learnerScore,attendance=attendanceRate,assess=assessmentRate;
const displayCampus=(name:string)=>shortNames[campuses.findIndex(c=>c.name===name)]||name;
const roles=[['dashboard-founder','Founder','Executive intelligence'],['dashboard-admissions','Admissions','Campus and online coaching pipeline'],['dashboard-campus','Centre Head','Campus academic and operational supervision'],['dashboard-parent','Parent','Individual learner progress'],['student','Student','Learning and practice']];
type Props={admissionsBusiness:string;setAdmissionsBusiness:(v:string)=>void;demoLearnerId:string;setDemoLearnerId:(id:string)=>void;tasks:Task[];setTasks:React.Dispatch<React.SetStateAction<Task[]>>;freeEvents:FreeEvent[];recordFree:(e:FreeEvent)=>void;page:string;section?:string;leads:Lead[];setLeads:React.Dispatch<React.SetStateAction<Lead[]>>;hrefFor:(id:string)=>string;learners:Learner[];setLearners:React.Dispatch<React.SetStateAction<Learner[]>>};
function Metric({label,value,detail}:{label:string;value:string|number;detail:string}){return <div className="bi-kpi"><small>{label}</small><strong>{typeof value==="number"?value.toLocaleString("en-IN"):value}</strong><span>{detail}</span></div>}
function Bars({rows,unit='%',max=100}:{rows:{label:string;value:number;detail?:string}[];unit?:string;max?:number}){return <div className="bi-bars">{rows.map(x=><div className="bi-bar" key={x.label}><span title={x.label}>{x.label}</span><div className="bi-track"><i style={{width:Math.min(100,Math.max(0,x.value/max*100))+'%'}}/></div><b>{unit==='%'?fmt(x.value):Math.round(x.value).toLocaleString('en-IN')+unit}</b>{x.detail&&<small>{x.detail}</small>}</div>)}</div>}
function Trend({rows}:{rows:{label:string;attendance:number;score:number}[]}){const xs=rows.map((_,i)=>55+i*390/Math.max(1,rows.length-1));const y=(v:number)=>180-v*1.5;return <figure className="bi-trend"><svg viewBox="0 0 500 220" role="img" aria-label="Monthly attendance and common assessment score percentages"><g>{[0,25,50,75,100].map(v=><g key={v}><line x1="45" x2="465" y1={y(v)} y2={y(v)} stroke="#e1e6e3"/><text x="38" y={y(v)+4} textAnchor="end" fill="#52605a" fontSize="10">{v}%</text></g>)}</g><polyline points={rows.map((r,i)=>xs[i]+','+y(r.attendance)).join(' ')} fill="none" stroke="#265844" strokeWidth="3"/><polyline points={rows.map((r,i)=>xs[i]+','+y(r.score)).join(' ')} fill="none" stroke="#861f35" strokeWidth="3" strokeDasharray="7 4"/>{rows.map((r,i)=><g key={r.label}><circle cx={xs[i]} cy={y(r.attendance)} r="4" fill="#265844"><title>{r.label+': attendance '+fmt(r.attendance)}</title></circle><circle cx={xs[i]} cy={y(r.score)} r="4" fill="#861f35"><title>{r.label+': score '+fmt(r.score)}</title></circle><text x={xs[i]} y="202" textAnchor="middle" fontSize="11" fill="#52605a">{r.label}</text></g>)}</svg><figcaption><span className="legend-green"><i aria-hidden="true"/>Attendance</span><span className="legend-red"><i aria-hidden="true"/>Mean assessment score</span></figcaption><details className="chart-values"><summary>View monthly values</summary><div className="bi-table"><table><thead><tr><th>Month</th><th className="numeric-cell">Attendance</th><th className="numeric-cell">Mean score</th></tr></thead><tbody>{rows.map(r=><tr key={r.label}><td>{r.label}</td><td className="numeric-cell">{fmt(r.attendance)}</td><td className="numeric-cell">{fmt(r.score)}</td></tr>)}</tbody></table></div></details></figure>}
