 const campusesSummary=campuses.map(c=>{const rs=cohort.filter(s=>s.campus===c.name);const ls=leads.filter(l=>l.campus===c.name);return {name:c.name,n:rs.length,attendance:attendance(rs,week),score:assess(rs,week),subjects:[0,1,2].map(k=>mean(rs.map(s=>s.marks[week][k]))),risk:rs.filter(s=>s.present[week]<24).length,leads:ls.length,converted:ls.filter(l=>l.status==='Converted').length}});
 const lowest=[...campusesSummary].sort((a,b)=>a.attendance-b.attendance)[0];
